import { LogoutOutlined, SettingOutlined, UserOutlined } from '@ant-design/icons'
import { Button, Dropdown, Menu, MenuProps } from 'antd'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useUserStore } from '@/shared/stores/useUserStore'
import { ServiceMenu } from '@/shared/types/serviceMenu'

interface LayoutHeaderProps {
    topmenu: ServiceMenu[]
    systemMenus: ServiceMenu[]
    setSelectedTopMenu: (menu: ServiceMenu | null) => void
}

const LayoutHeader = ({ topmenu, systemMenus, setSelectedTopMenu }: LayoutHeaderProps) => {
    const viewUser = useUserStore((state) => state.user)
    const router = useRouter()

    const onLogout = () => {
        window.location.href = '/api/auth/logout'
    }

    // 일반사용자 드롭다운 메뉴
    const clientDropdownItems: MenuProps['items'] = [
        {
            key: 'logout',
            label: '로그아웃',
            icon: <LogoutOutlined />,
            onClick: onLogout
        }
    ]

    const adminDropdownItems: MenuProps['items'] = systemMenus.map((menu) => ({
        key: menu.id.toString(),
        label: menu.name,
        onClick: () => {
            if (menu.url) {
                router.push(menu.url)
            }
        }
    }))

    // 1Depth 메뉴 (메인 메뉴만)
    const TopMenuItems: MenuProps['items'] = topmenu.map((menu) => ({
        key: menu.id.toString(),
        label: <div className="px-3">{menu.name}</div>,
        onClick: () => {
            if (menu.subMenus && menu.subMenus?.length > 0) {
                // 서브메뉴가 있으면 사이드바 표시
                setSelectedTopMenu(menu)
            } else {
                // 서브메뉴가 없으면 사이드바 숨기고 URL로 이동
                setSelectedTopMenu(null)
                if (menu.url) {
                    router.push(menu.url)
                }
            }
        }
    }))

    return (
        <>
            <header className="relative border-b border-gray-200 bg-gray-50">
                {/* 1Depth 메뉴만 */}
                <div className="flex h-14 items-center justify-between px-6">
                    <div className="flex h-full items-center gap-8">
                        {/* 로고 */}
                        <div className="flex h-full items-center">
                            <Link href="/" className="block">
                                <div className="hidden text-xl font-bold text-black sm:block">통합관리자</div>
                                <div className="text-2xl font-bold text-black sm:hidden">CADMIN</div>
                            </Link>
                        </div>

                        {/* 메뉴 */}
                        <div className="flex h-full min-w-0 flex-1 items-center">
                            <Menu
                                className="border-none bg-transparent"
                                items={TopMenuItems}
                                mode="horizontal"
                                disabledOverflow={true}
                            />
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        {/* 관리자 드롭다운 */}
                        {adminDropdownItems.length > 0 && (
                            <Dropdown menu={{ items: adminDropdownItems }} placement="bottom" arrow>
                                <Button icon={<SettingOutlined />} />
                            </Dropdown>
                        )}

                        {/* 사용자 드롭다운 */}
                        <Dropdown menu={{ items: clientDropdownItems }} placement="bottomRight">
                            <Button icon={<UserOutlined />}>{viewUser?.nickname}</Button>
                        </Dropdown>
                    </div>
                </div>
            </header>
        </>
    )
}

export default LayoutHeader

